"""matplotlib.textpath — text-to-path conversion stub.

Real matplotlib uses this to render text along arbitrary paths
(`TextPath`, `TextToPath`). The plotly backend renders text natively,
so these classes exist only as no-op placeholders that satisfy
`from matplotlib.textpath import TextPath` imports.
"""

import numpy as np
from matplotlib.path import Path


class TextPath(Path):
    """Stub TextPath — produces a single-vertex Path so isinstance
    checks pass and bounding-box queries return reasonable defaults."""

    def __init__(self, xy, s, size=None, prop=None, _interpolation_steps=1,
                 usetex=False):
        super().__init__([list(xy)])
        self._xy = xy
        self._s = s
        self._size = size or 12

    def get_size(self):     return self._size
    def set_size(self, sz): self._size = sz


class TextToPath:
    def __init__(self): pass
    def glyph_to_path(self, font, currx=0): return np.zeros((0, 2)), np.array([], dtype=np.uint8)
    def get_text_path(self, prop, s, ismath=False): return np.zeros((0, 2)), np.array([], dtype=np.uint8)
    def get_glyphs_with_font(self, font, s, glyph_map=None, return_new_glyphs_only=False):
        return [], {}, []
    def get_glyphs_tex(self, prop, s, glyph_map=None, return_new_glyphs_only=False):
        return [], {}, []


text_to_path = TextToPath()


# ─── Added: TextToPath constants ────────────────────────────────────


TextToPath.DPI        = 72
TextToPath.FONT_SCALE = 100.0

def _ttp_get_glyphs_mathtext(self, prop, s, glyph_map=None, return_new_glyphs_only=False):
    return [], {}, []
def _ttp_get_text_width_height_descent(self, s, prop, ismath=False):
    return 0, 0, 0

TextToPath.get_glyphs_mathtext             = _ttp_get_glyphs_mathtext
TextToPath.get_text_width_height_descent   = _ttp_get_text_width_height_descent
